//! Replays the real-OPA-evaluated corpus in `rust/conformance/vectors/policy/{scope,permission,
//! action}.json` (generated by `rust/conformance/vectors/generators/policy`, pinned to
//! `GOTOOLCHAIN=go1.26.10`, from the vendor bundle in `../vendor`) against this crate's `regorus`
//! [`silo_gate::policy::Engine`], and asserts every decision agrees.
//!
//! This is the plan's "measured against OPA on an accept/reject corpus" gate for `policy` (see
//! `docs/superpowers/rust-port/plan.md`'s decision table) and this task's exit-gate line
//! "vendored policy decisions agree with real OPA on a randomized corpus of at least 5,000
//! inputs": the three files together hold 10,500 cases (2,500 base-decision + 1,000 override cases
//! per domain), each including a case with a custom `silo_custom.<domain>.override` source so the
//! `tighten` paths are exercised too, not just the stub's always-`false` path.
//!
//! Regenerate with:
//! ```text
//! GOTOOLCHAIN=go1.26.10 go run ./rust/conformance/vectors/generators/policy \
//!   -vendor rust/crates/silo-gate/vendor -out rust/conformance/vectors/policy \
//!   -n 2500 -n-override 1000 -seed 1
//! ```

use std::collections::BTreeMap;

use serde::Deserialize;
use silo_gate::policy::{Domain, Engine};

#[derive(Deserialize)]
struct CaseRecord {
    input: serde_json::Value,
    #[serde(default)]
    r#override: Option<serde_json::Value>,
    decision: serde_json::Value,
}

fn load_cases(name: &str) -> Vec<CaseRecord> {
    // Not a Go-semantics path (no symlink/separator-quirk parity at stake, just this crate's own
    // fixture layout), but `join` is banned workspace-wide; `silo_gocompat::filepath::join` works
    // fine for an ordinary relative join like this one too.
    let path = silo_gocompat::filepath::join(&[
        env!("CARGO_MANIFEST_DIR"),
        "../../conformance/vectors/policy",
        &format!("{name}.json"),
    ]);
    let data = std::fs::read(&path).unwrap_or_else(|e| {
        panic!("reading {path:?}: {e} (did you run the generator? see this file's doc comment)")
    });
    silo_gocompat::json::unmarshal(&data).expect("parsing vector file")
}

/// Rego's `data.silo_custom.<domain>.override` output converts unset-via-`undefined` into the
/// base decision; a case with no override must run against the vendor stub, which always fails
/// its body (`false`), so it needs no synthetic module and `Engine::new()` already does the right
/// thing. A case with an override document needs a synthetic module in its place, same as the
/// generator did when it asked real OPA for that case's decision.
fn run_domain(name: &str, domain: Domain) {
    let cases = load_cases(name);
    assert!(
        cases.len() >= 2000,
        "{name}: expected a substantial corpus, got {} cases",
        cases.len()
    );
    let mut checked = 0usize;
    for (i, case) in cases.iter().enumerate() {
        let mut custom = BTreeMap::new();
        if let Some(override_doc) = &case.r#override {
            let source = format!(
                "package silo_custom.{domain}\n\nimport rego.v1\n\noverride(_, _) := {}\n",
                override_doc
            );
            custom.insert(domain, source);
        }
        let mut engine = Engine::with_custom(&custom).unwrap_or_else(|e| {
            panic!(
                "{name} case {i}: building engine with override {:?}: {e}",
                case.r#override
            )
        });
        let got = engine
            .evaluate_json(domain, &case.input)
            .unwrap_or_else(|e| {
                panic!(
                    "{name} case {i}: regorus eval failed where OPA succeeded: {e}\ninput: {}",
                    case.input
                )
            });
        assert_eq!(
            got, case.decision,
            "{name} case {i} diverges from real OPA\ninput: {}\noverride: {:?}",
            case.input, case.r#override
        );
        checked += 1;
    }
    eprintln!("{name}: {checked} cases agreed with real OPA");
}

#[test]
fn scope_decisions_agree_with_real_opa() {
    run_domain("scope", Domain::Scope);
}

#[test]
fn permission_decisions_agree_with_real_opa() {
    run_domain("permission", Domain::Permission);
}

#[test]
fn action_decisions_agree_with_real_opa() {
    run_domain("action", Domain::Action);
}

#[test]
fn corpus_totals_at_least_5000_inputs() {
    let total =
        load_cases("scope").len() + load_cases("permission").len() + load_cases("action").len();
    assert!(
        total >= 5000,
        "expected at least 5000 total cases, got {total}"
    );
}
